using VtuberFriends;
using System.Diagnostics;
internal static class TokenVaultCompatibilityProbe{
 public static void Run(){if(!OperatingSystem.IsWindows())return;string dir=Path.Combine(Path.GetTempPath(),"vf-vault-compat-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string path=Path.Combine(dir,"synthetic.dpapi"),quoted=path.Replace("'","''");
  void PowerShell(string script){var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32","WindowsPowerShell","v1.0","powershell.exe")){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};info.Environment.Remove("PSModulePath");info.ArgumentList.Add("-NoProfile");info.ArgumentList.Add("-Command");info.ArgumentList.Add("$ErrorActionPreference='Stop';"+script);using var process=Process.Start(info)!;if(!process.WaitForExit(10000)){process.Kill();throw new Exception("Synthetic vault compatibility timed out.");}if(process.ExitCode!=0)throw new Exception("Synthetic vault PowerShell compatibility failed: "+process.StandardError.ReadToEnd());}
  try{PowerShell("$s=ConvertTo-SecureString 'SYNTHETIC_VAULT_ONLY' -AsPlainText -Force;[IO.File]::WriteAllText('"+quoted+"',(ConvertFrom-SecureString $s))");if(TokenVault.Read(path)!="SYNTHETIC_VAULT_ONLY")throw new Exception("Cannot read PowerShell vault.");TokenVault.Save(path,"SYNTHETIC_VAULT_ONLY");PowerShell("$s=ConvertTo-SecureString ([IO.File]::ReadAllText('"+quoted+"'));if([Net.NetworkCredential]::new('',$s).Password -ne 'SYNTHETIC_VAULT_ONLY'){exit 2}");Console.WriteLine("PASS: DPAPI compatible en ambas direcciones con Windows PowerShell, solo secreto sintetico.");}finally{File.Delete(path);Directory.Delete(dir);}
 }
}
